# ---- helpers for the remaining sections: rx is a raw string with single backslashes; post is appended to the expression
# amendments that the truth index files under the paper-writing sources (not primary): the formula then reads the log file itself with a unique pattern
LOGFILE_AMENDS = {1749, 1752, 1820, 1916, 2160, 2038, 2070, 2075}
def _src(amend, rx):
    if amend in LOGFILE_AMENDS:
        return "T('temporal_within/PREREG_Q32.md', r'%s')" % rx
    return "L(%d, r'%s')" % (amend, rx)
def LB(printed, ctx, amend, rx, why, post="", kind=None):
    B(printed, ctx, "%s%s" % (_src(amend, rx), post), why, kind)
def PW(printed, ctx, amend, rx, why, post="", kind=None):
    B(printed, ctx, "10**(-%s)" % _src(amend, rx), why, kind)
def TB(printed, ctx, path, rx, why, post="", kind=None):
    B(printed, ctx, "T('%s', r'%s')%s" % (path, rx, post), why, kind)
